mapper.select:
select d.user_id userId,d.nickname,d.avatar,d.weight,d.height,d.birthday
from tlx_activity_user u left join corgi_user_detail d on d.user_id = u.user_id
where u.status = 1
and u.activity_id = #{activityId}
order by u.id desc limit 200;

select count(1)
from tlx_activity_user u
where u.status = 1
  and u.activity_id = #{activityId}
  and u.user_id = #{userId}
